//! Snapshot compatibility is separate from raw-byte equality. Only fields proven
//! to be generated by this request may vary; stored content and aliases stay exact.
use anyhow::{Result, ensure};
use loro::{Container, ContainerID, ContainerTrait, LoroDoc, ToJson, ValueOrContainer};
use macro_document_model::{DocumentContext, NodeClock, NodeRandom, notion::NotionLinks};
use serde_json::{Value, json};
use std::{
    collections::{BTreeMap, HashMap},
    sync::Arc,
};

#[derive(Clone)]
pub(crate) struct SnapshotInput {
    pub(crate) markdown: String,
    pub(crate) notion: Option<NotionLinks>,
}
impl SnapshotInput {
    fn state(&self, seed: u8) -> Result<Value> {
        let context = DocumentContext {
            clock: NodeClock(Arc::new(move || 1_700_000_000_000 + u64::from(seed))),
            random: NodeRandom(Arc::new(move |length| vec![seed; length])),
            ..crate::in_process::context()
        };
        let state = match &self.notion {
            None => macro_document_model::markdown::markdown_to_serialized_editor_state_with_ids(
                &self.markdown,
                &context,
            )?,
            Some(links) => {
                macro_document_model::notion::notion_markdown_to_serialized_editor_state(
                    &self.markdown,
                    links,
                    &context,
                )?
            }
        };
        Ok(serde_json::to_value(state)?)
    }
    fn frozen(&self) -> bool {
        if self.notion.is_some() {
            lexical_model::js_trim(&self.markdown).is_empty()
        } else {
            self.markdown.is_empty()
        }
    }
}
#[derive(Clone)]
enum Segment {
    Key(String),
    Index(usize),
}
#[derive(Clone, Copy)]
enum Generated {
    Id,
    Milliseconds,
    IsoTime,
    AwaitId,
}
struct Field {
    path: Vec<Segment>,
    kind: Generated,
}

// Probe only constructor-owned identity/time fields. Authored values remain
// unchanged across the two probes, so they are never eligible for normalization.
fn fields(left: &Value, right: &Value, path: &mut Vec<Segment>, output: &mut Vec<Field>) {
    match (left, right) {
        (Value::Object(a), Value::Object(b)) => {
            for (name, value) in a {
                let Some(other) = b.get(name) else {
                    continue;
                };
                path.push(Segment::Key(name.clone()));
                let kind = match name.as_str() {
                    "id" if matches!(path.iter().rev().nth(1), Some(Segment::Key(parent)) if parent == "$") => {
                        Some(Generated::Id)
                    }
                    "createdAt"
                        if a.get("type").and_then(Value::as_str) == Some("document-mention") =>
                    {
                        Some(Generated::Milliseconds)
                    }
                    "snapshotDate" if a.get("type").and_then(Value::as_str) == Some("snapshot") => {
                        Some(Generated::IsoTime)
                    }
                    "awaitId" if a.get("type").and_then(Value::as_str) == Some("await") => {
                        Some(Generated::AwaitId)
                    }
                    _ => None,
                };
                if let Some(kind) = kind.filter(|_| value != other) {
                    output.push(Field {
                        path: path.clone(),
                        kind,
                    });
                } else {
                    fields(value, other, path, output);
                }
                path.pop();
            }
        }
        (Value::Array(a), Value::Array(b)) => {
            for (index, (value, other)) in a.iter().zip(b).enumerate() {
                path.push(Segment::Index(index));
                fields(value, other, path, output);
                path.pop();
            }
        }
        _ => {}
    }
}
fn at_mut<'a>(value: &'a mut Value, path: &[Segment]) -> Option<&'a mut Value> {
    let mut value = value;
    for segment in path {
        value = match segment {
            Segment::Key(key) => value.get_mut(key)?,
            Segment::Index(index) => value.get_mut(*index)?,
        };
    }
    Some(value)
}
fn generated_string(value: &Value, length: usize) -> bool {
    value.as_str().is_some_and(|s| {
        s.len() == length
            && s.bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'_' || b == b'-')
    })
}
fn normalize(left: &mut Value, right: &mut Value, fields: &[Field]) -> Result<()> {
    let mut forward = HashMap::new();
    let mut reverse = HashMap::new();
    for field in fields {
        let a =
            at_mut(left, &field.path).ok_or_else(|| anyhow::anyhow!("missing generated field"))?;
        let b =
            at_mut(right, &field.path).ok_or_else(|| anyhow::anyhow!("missing generated field"))?;
        match field.kind {
            Generated::Id | Generated::AwaitId => {
                let length = if matches!(field.kind, Generated::Id) {
                    8
                } else {
                    21
                };
                ensure!(
                    generated_string(a, length) && generated_string(b, length),
                    "invalid generated identity"
                );
                let source = a
                    .as_str()
                    .ok_or_else(|| anyhow::anyhow!("invalid identity"))?
                    .to_owned();
                let target = b
                    .as_str()
                    .ok_or_else(|| anyhow::anyhow!("invalid identity"))?
                    .to_owned();
                ensure!(
                    forward.get(&source).is_none_or(|v| v == &target)
                        && reverse.get(&target).is_none_or(|v| v == &source),
                    "identity aliases differ"
                );
                forward.insert(source.clone(), target.clone());
                reverse.insert(target, source);
            }
            Generated::Milliseconds => ensure!(
                a.as_u64().is_some() && b.as_u64().is_some(),
                "invalid generated timestamp"
            ),
            Generated::IsoTime => ensure!(
                a.as_str()
                    .is_some_and(|s| chrono::DateTime::parse_from_rfc3339(s).is_ok())
                    && b.as_str()
                        .is_some_and(|s| chrono::DateTime::parse_from_rfc3339(s).is_ok()),
                "invalid generated ISO timestamp"
            ),
        }
        // Only these explicit paths vary. A string elsewhere, even one equal to
        // an identity, stays exact; arbitrary payloads are never rewritten.
        *a = Value::Null;
        *b = Value::Null;
    }
    Ok(())
}

// Container kind and sharing are part of compatibility, even if deep JSON is
// equal. Stable traversal assigns a canonical ordinal to each container alias.
fn shape(value: ValueOrContainer, seen: &mut HashMap<ContainerID, usize>) -> Result<Value> {
    let ValueOrContainer::Container(container) = value else {
        return Ok(json!("value"));
    };
    let id = container.id();
    if let Some(index) = seen.get(&id) {
        return Ok(json!({"ref": index}));
    }
    let index = seen.len();
    seen.insert(id, index);
    Ok(match container {
        Container::Map(map) => {
            let mut entries = BTreeMap::new();
            map.for_each(|key, value| {
                entries.insert(key.to_owned(), value);
            });
            let entries = entries
                .into_iter()
                .map(|(key, value)| Ok((key, shape(value, seen)?)))
                .collect::<Result<BTreeMap<_, _>>>()?;
            json!({"map":entries,"id":index})
        }
        Container::List(list) => {
            let mut entries = Vec::new();
            for i in 0..list.len() {
                entries.push(shape(
                    list.get(i)
                        .ok_or_else(|| anyhow::anyhow!("missing list item"))?,
                    seen,
                )?);
            }
            json!({"list":entries,"id":index})
        }
        Container::MovableList(list) => {
            let mut entries = Vec::new();
            for i in 0..list.len() {
                entries.push(shape(
                    list.get(i)
                        .ok_or_else(|| anyhow::anyhow!("missing movable list item"))?,
                    seen,
                )?);
            }
            json!({"movableList":entries,"id":index})
        }
        Container::Text(text) => json!({"text":text.to_delta(),"id":index}),
        _ => anyhow::bail!("unsupported snapshot container"),
    })
}
fn decode(bytes: &[u8]) -> Result<(Value, Value)> {
    let doc = LoroDoc::new();
    doc.import(bytes)?;
    let base = LoroDoc::new();
    base.import(lexical_loro::golden::MARKDOWN_GOLDEN)?;
    ensure!(
        doc.oplog_vv().includes_vv(&base.oplog_vv()),
        "snapshot lost golden ancestry"
    );
    let root = doc.get_map("root");
    ensure!(
        root.id() == base.get_map("root").id(),
        "root container changed"
    );
    for name in ["$", "children"] {
        let Some(ValueOrContainer::Container(value)) = root.get(name) else {
            anyhow::bail!("missing ancestor container");
        };
        let Some(ValueOrContainer::Container(original)) = base.get_map("root").get(name) else {
            anyhow::bail!("invalid golden container");
        };
        ensure!(value.id() == original.id(), "ancestor container changed");
    }
    Ok((
        doc.get_deep_value().to_json_value(),
        shape(
            ValueOrContainer::Container(root.to_container()),
            &mut HashMap::new(),
        )?,
    ))
}
pub(crate) fn compatible(input: &SnapshotInput, left: Value, right: Value) -> Result<bool> {
    let (left, right) = if input.notion.is_some() {
        ensure!(
            left.get("markdown") == right.get("markdown"),
            "Notion Markdown differs"
        );
        (
            left.get("snapshot")
                .cloned()
                .ok_or_else(|| anyhow::anyhow!("missing snapshot"))?,
            right
                .get("snapshot")
                .cloned()
                .ok_or_else(|| anyhow::anyhow!("missing snapshot"))?,
        )
    } else {
        (left, right)
    };
    let left: Vec<u8> = serde_json::from_value(left)?;
    let right: Vec<u8> = serde_json::from_value(right)?;
    if input.frozen() {
        return Ok(left == lexical_loro::golden::MARKDOWN_GOLDEN
            && right == lexical_loro::golden::MARKDOWN_GOLDEN);
    }
    let (mut a, a_shape) = decode(&left)?;
    let (mut b, b_shape) = decode(&right)?;
    ensure!(a_shape == b_shape, "snapshot container shape differs");
    let mut generated = Vec::new();
    fields(
        &input.state(7)?,
        &input.state(9)?,
        &mut Vec::new(),
        &mut generated,
    );
    normalize(&mut a, &mut b, &generated)?;
    Ok(a == b)
}

